                // payload must reserve the room its glyph occupies, and the leading
                // around it is removed again by `contentInsetTopEm`.
                const top = ink === null ? rect.top : ink.top;
                const bottom = ink === null ? rect.bottom : ink.bottom;
                const hasBaseline = Number.isFinite(baseline) && baseline > 0;
